use std::path::PathBuf;

// Compiles the vendored libopus 1.4 C sources (Xiph.Org Foundation, BSD
// three-clause) into the crate. config.h was pre-generated by a normal
// ./configure run on a Linux host and committed with the sources; the
// x86 RTCD and ARM NEON dispatch paths are trimmed out of it, so only
// the portable C sources compile.
fn main() {
    let root = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap()).join("vendor");
    let mut build = cc::Build::new();
    build
        .define("HAVE_CONFIG_H", None)
        .include(&root)
        .include(root.join("include"))
        .include(root.join("celt"))
        .include(root.join("silk"))
        .include(root.join("silk/float"))
        .include(root.join("src"))
        .flag("-O2");
    let mut n = 0;
    for dir in ["celt", "silk", "silk/float", "src"] {
        for entry in walk(&root.join(dir)) {
            let ps = entry.to_string_lossy().replace('\\', "/");
            let name = entry.file_name().unwrap().to_string_lossy().to_string();
            let skip = ps.contains("test")
                || ps.contains("demo")
                || ps.contains("compare")
                || ps.contains("/arm/")
                || ps.contains("/x86/")
                || ps.contains("/fixed/");
            if name.ends_with(".c") && !skip {
                build.file(entry);
                n += 1;
            }
        }
    }
    println!("cargo:warning=svc_client: compiling {} libopus C sources", n);
    build.compile("opus");
}

fn walk(dir: &std::path::Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(rd) = std::fs::read_dir(dir) {
        for e in rd.flatten() {
            let p = e.path();
            if p.is_dir() {
                out.extend(walk(&p));
            } else {
                out.push(p);
            }
        }
    }
    out
}
